package local.pitv;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.util.concurrent.*;
final class MoviePhotoReel extends LinearLayout {
 static final String[] TITLES={"Back to the Future \u00b7 1985","Ghostbusters \u00b7 1984","The Goonies \u00b7 1985","E.T. the Extra-Terrestrial \u00b7 1982","Raiders of the Lost Ark \u00b7 1981","The Karate Kid \u00b7 1984","Gremlins \u00b7 1984","Beetlejuice \u00b7 1988","Who Framed Roger Rabbit \u00b7 1988","The Princess Bride \u00b7 1987","Ferris Bueller's Day Off \u00b7 1986","The Breakfast Club \u00b7 1985","Big (film) \u00b7 1988","Labyrinth (1986 film) \u00b7 1986","The NeverEnding Story (film) \u00b7 1984","The Dark Crystal \u00b7 1982","The Terminator \u00b7 1984","RoboCop \u00b7 1987","Alien (film) \u00b7 1979","Aliens (film) \u00b7 1986","Blade Runner \u00b7 1982","Tron \u00b7 1982","Jurassic Park \u00b7 1993","Home Alone \u00b7 1990","Mrs. Doubtfire \u00b7 1993","Jumanji \u00b7 1995","The Sandlot \u00b7 1993","Hook (film) \u00b7 1991","Groundhog Day (film) \u00b7 1993","Space Jam \u00b7 1996","The Mask (1994 film) \u00b7 1994","Bill & Ted's Excellent Adventure \u00b7 1989","Wayne's World (film) \u00b7 1992","Beverly Hills Cop \u00b7 1984","Ghostbusters II \u00b7 1989","Back to the Future Part II \u00b7 1989","Footloose \u00b7 1984","Dirty Dancing \u00b7 1987","Stand by Me \u00b7 1986","Toy Story \u00b7 1995","La La Land \u00b7 2016","Oppenheimer \u00b7 2023","The Lion King \u00b7 1994","The Wild Robot \u00b7 2024","Pirates of the Caribbean: The Curse of the Black Pearl \u00b7 2003","Forrest Gump \u00b7 1994","The Matrix \u00b7 1999","The Truman Show \u00b7 1998","Men in Black \u00b7 1997","The Iron Giant \u00b7 1999","Knives Out \u00b7 2019","Everything Everywhere All at Once \u00b7 2022","Top Gun: Maverick \u00b7 2022","Dune: Part Two \u00b7 2024","Inside Out 2 \u00b7 2024","Wicked \u00b7 2024","Zootopia 2 \u00b7 2025","Shrek \u00b7 2001","Spirited Away \u00b7 2001","The Lord of the Rings: The Fellowship of the Ring \u00b7 2001","Interstellar \u00b7 2014","Finding Nemo \u00b7 2003","The Incredibles \u00b7 2004","The Dark Knight \u00b7 2008","Mad Max: Fury Road \u00b7 2015","Coco \u00b7 2017","Black Panther \u00b7 2018","Spider-Man: Into the Spider-Verse \u00b7 2018","The Super Mario Galaxy Movie \u00b7 2026","Toy Story 5 \u00b7 2026","Project Hail Mary \u00b7 2026","Batman \u00b7 1989","The Rocketeer \u00b7 1991","Matilda \u00b7 1996","The Mummy \u00b7 1999","Galaxy Quest \u00b7 1999","School of Rock \u00b7 2003","Elf \u00b7 2003","The Emperor's New Groove \u00b7 2000","Monsters, Inc. \u00b7 2001","WALL-E \u00b7 2008","Guardians of the Galaxy \u00b7 2014","Moana \u00b7 2016","Puss in Boots: The Last Wish \u00b7 2022","Wonka \u00b7 2023","Beetlejuice Beetlejuice \u00b7 2024","Sonic the Hedgehog 3 \u00b7 2024","A Minecraft Movie \u00b7 2025"};
 final java.util.ArrayList<Integer> order=new java.util.ArrayList<>();final Handler handler=new Handler();final ExecutorService worker=Executors.newSingleThreadExecutor();final Bitmap[] images=new Bitmap[TITLES.length];final ImageView image;final ImageView[] posters=new ImageView[3];final TextView caption;boolean active=false,closed=false;int index=0;long remaining=8000,due;final Runnable rotate=new Runnable(){public void run(){due=0;if(!active||closed||hasFocus())return;index=(index+1)%Math.max(1,order.size());remaining=8000;savePosition();showPhoto();schedule();}};
 MoviePhotoReel(Context c){super(c);setOrientation(VERTICAL);setPadding(0,TvStyle.dp(c,6),0,0);setFocusable(true);setClickable(true);setBackground(TvStyle.shape(c,0x00000000,0x00000000));setOnFocusChangeListener((v,focused)->{setBackground(TvStyle.shape(c,0x00000000,focused?TvStyle.CYAN:0x00000000));freeze();if(!focused&&active)schedule();});setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0)move(key==KeyEvent.KEYCODE_DPAD_LEFT?-1:1);return true;}return false;});setOnClickListener(v->move(1));LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER);for(int n=0;n<3;n++){ImageView poster=new ImageView(c);poster.setScaleType(ImageView.ScaleType.FIT_CENTER);poster.setFocusable(false);poster.setAlpha(n==1?1f:0.55f);poster.setScaleY(n==1?1f:0.82f);posters[n]=poster;LayoutParams lp=new LayoutParams(0,-1,n==1?1.15f:0.85f);lp.setMargins(TvStyle.dp(c,4),0,TvStyle.dp(c,4),0);row.addView(poster,lp);}image=posters[1];addView(row,new LayoutParams(-1,0,1));caption=TvStyle.text(c,"Loading movie posters…",14);caption.setGravity(Gravity.CENTER);caption.setSingleLine(true);addView(caption,new LayoutParams(-1,TvStyle.dp(c,26)));restorePosition();showPhoto(false);for(int item:order)worker.submit(()->load(item));}
 void move(int direction){index=(index+direction+Math.max(1,order.size()))%Math.max(1,order.size());remaining=8000;due=0;handler.removeCallbacks(rotate);savePosition();showPhoto();schedule();}
 void load(int item){try(java.io.InputStream in=getContext().getAssets().open("movie-posters/"+item+".jpg")){BitmapFactory.Options options=new BitmapFactory.Options();options.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap bitmap=BitmapFactory.decodeStream(in,null,options);if(bitmap==null)return;handler.post(()->{if(closed){bitmap.recycle();return;}images[item]=bitmap;for(int n=0;n<3;n++)if(order.get((index+n-1+order.size())%order.size())==item){showPhoto(false);break;}});}catch(Exception ignored){}}
 void showPhoto(){showPhoto(true);}
 void showPhoto(boolean animate){if(order.isEmpty())return;index=index%order.size();caption.setText(TITLES[order.get(index)]);setContentDescription("Retro movie carousel: "+TITLES[order.get(index)]+". Left or right to browse.");for(int n=0;n<3;n++){int item=order.get((index+n-1+order.size())%order.size());posters[n].setImageBitmap(images[item]);posters[n].setContentDescription(TITLES[item]+" movie poster");}if(animate&&active&&!getContext().getSharedPreferences("tv",0).getBoolean("reduceMotion",false)){image.animate().cancel();image.setAlpha(0.3f);image.setTranslationX(TvStyle.dp(getContext(),12));image.animate().alpha(1f).translationX(0).setDuration(450).start();}}
 void restorePosition(){android.content.SharedPreferences p=getContext().getSharedPreferences("display-positions",0);try{org.json.JSONArray saved=new org.json.JSONArray(p.getString("posterOrder","[]"));for(int n=0;n<saved.length();n++){int item=saved.getInt(n);if(item>=0&&item<TITLES.length&&!order.contains(item))order.add(item);}}catch(Exception ignored){}java.util.ArrayList<Integer> added=new java.util.ArrayList<>();for(int item=0;item<TITLES.length;item++)if(!order.contains(item))added.add(item);java.util.Collections.shuffle(added);order.addAll(added);index=Math.max(0,p.getInt("posterIndex",0))%order.size();remaining=Math.max(1,Math.min(8000,p.getLong("posterRemaining",8000)));savePosition();}
 void savePosition(){getContext().getSharedPreferences("display-positions",0).edit().putString("posterOrder",new org.json.JSONArray(order).toString()).putInt("posterIndex",index).putLong("posterRemaining",remaining).apply();}
 void freeze(){if(due>0)remaining=Math.max(1,due-android.os.SystemClock.uptimeMillis());due=0;handler.removeCallbacks(rotate);}
 void schedule(){handler.removeCallbacks(rotate);if(active&&!closed&&!hasFocus()){due=android.os.SystemClock.uptimeMillis()+remaining;handler.postDelayed(rotate,remaining);}}
 void resume(){if(closed||active)return;active=true;showPhoto(false);schedule();}
 void pause(){freeze();active=false;savePosition();image.animate().cancel();}
 void close(){pause();closed=true;worker.shutdownNow();handler.removeCallbacksAndMessages(null);for(ImageView poster:posters)poster.setImageDrawable(null);for(Bitmap bitmap:images)if(bitmap!=null)bitmap.recycle();}
}
